 internal void SaveTemplate(){if(current==null||!SaveNow())return;string name=Ask("Save reusable template","Template name",current.Title);if(name==null)return;string f=Path.Combine(store.Home,"Templates",Store.Clean(name)+".md");if(File.Exists(f)&&MessageBox.Show(this,"Replace this template?","Save template",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;Store.Atomic(f,editor.Text);Tell("Template saved · Templates menu");}

 internal void DeleteNote(){DeletePage(current,true);}


 internal string Ask(string title,string label,string value){using(var f=Dialog(title,500,220)){var t=new TextBox{Text=value,Dock=DockStyle.Top};f.Controls.Add(t);f.Controls.Add(new Label{Text=label,Dock=DockStyle.Top,Height=58});var ok=new Button{Text="Save",Dock=DockStyle.Bottom,Height=40,DialogResult=DialogResult.OK};f.Controls.Add(ok);f.AcceptButton=ok;return f.ShowDialog(this)==DialogResult.OK?t.Text:null;}}

 internal Form Dialog(string title,int w,int h){var form=new Form{Text=title,Size=new Size(w,h),MinimumSize=new Size(w,h),StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=panel,ForeColor=ink,Padding=new Padding(20),ShowInTaskbar=false};DialogChrome(form);return form;}

 internal void Open(string path){Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}

 internal static Icon MakeIcon(){using(var b=new Bitmap(64,64))using(var g=Graphics.FromImage(b)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.Clear(Color.Transparent);using(var fill=new SolidBrush(Color.FromArgb(72,109,110)))g.FillRectangle(fill,9,5,44,54);using(var p=new Pen(Color.FromArgb(248,246,240),4)){g.DrawLine(p,19,20,43,20);g.DrawLine(p,19,30,39,30);g.DrawLine(p,19,40,32,40);}IntPtr h=b.GetHicon();var icon=(Icon)Icon.FromHandle(h).Clone();DestroyIcon(h);return icon;}}

 [DllImport("user32.dll")]static extern bool DestroyIcon(IntPtr icon);

 internal void ApplyTheme(string name){store.Pref.Theme=name;string[] colors;switch(name.ToLowerInvariant()){case "charcoal":colors=new[]{"#202329","#2b2f36","#ecede9","#b6bdc5","#d6c89e"};break;case "forest":colors=new[]{"#203630","#334e40","#f2ebd2","#b9cabb","#b7d5a0"};break;case "blueprint":colors=new[]{"#1a3146","#2b465c","#deeff5","#acc6d5","#91d9f4"};break;case "plum":colors=new[]{"#27202e","#352c3f","#f0e7f4","#bfafc9","#ddb4db"};break;case "paper":colors=new[]{"#f5eedf","#fffbf1","#483a2f","#786f61","#8f663e"};break;case "candy":colors=new[]{"#f0e6ef","#fff3f8","#533650","#7d6075","#9e4e87"};break;default:colors=new[]{"#e9e5dd","#f8f6f0","#27363a","#69716b","#486d6e"};break;}bg=ColorTranslator.FromHtml(colors[0]);panel=ColorTranslator.FromHtml(colors[1]);ink=ColorTranslator.FromHtml(colors[2]);muted=ColorTranslator.FromHtml(colors[3]);accent=ColorTranslator.FromHtml(colors[4]);ThemeControls(this);ThemePopups();store.SavePrefs();ApplyFloating();UpdatePageView();Invalidate(true);}

 internal void ThemeItems(ToolStripItemCollection items){foreach(ToolStripItem item in items){item.ForeColor=ink;item.BackColor=panel;var menu=item as ToolStripDropDownItem;if(menu!=null){menu.DropDown.Renderer=new ToolStripProfessionalRenderer(new CompanionColors(panel,bg,accent));ThemeItems(menu.DropDownItems);}}}
 internal void ThemeControls(Control c){CompanionPalette.Apply(c,store.Pref.Theme);}

 protected override bool ProcessCmdKey(ref Message msg,Keys key){if(notes.Focused&&key==Keys.Delete){DeleteSelectedPages();return true;}if(notes.Focused&&key==(Keys.Control|Keys.Z)){RestoreDeletedPage();return true;}if((key==(Keys.Control|Keys.Oemplus)||key==(Keys.Control|Keys.Add))&&editor.Focused){SetNotebookFont(store.Pref.EditorFont,store.Pref.EditorSize+1);return true;}if((key==(Keys.Control|Keys.OemMinus)||key==(Keys.Control|Keys.Subtract))&&editor.Focused){SetNotebookFont(store.Pref.EditorFont,store.Pref.EditorSize-1);return true;}if(view=="Tasks"&&tasks.Focused&&key==Keys.Delete){RemoveTask();return true;}if(view=="Tasks"&&(key==(Keys.Control|Keys.Z)||key==(Keys.Control|Keys.Y)||key==(Keys.Control|Keys.Shift|Keys.Z))&&!taskEntry.Focused){UndoNote(key!=(Keys.Control|Keys.Z));return true;}if(key==(Keys.Control|Keys.N)){NewNote("Quick note","");return true;}if(key==(Keys.Control|Keys.S)){SaveNow();return true;}if(key==(Keys.Control|Keys.V)&&editor.Focused&&Clipboard.ContainsImage()){using(var image=Clipboard.GetImage())using(var bitmap=new Bitmap(image))using(var edit=new CaptureEditor(bitmap,this))edit.ShowDialog();return true;}if(key==(Keys.Control|Keys.F)){ShowFind();return true;}if(key==(Keys.Control|Keys.Shift|Keys.F)){SetMemo(false);if(split.Panel1Collapsed)Compact(false);search.Focus();return true;}if(key==Keys.F3){FindNext(false);return true;}if(key==(Keys.Shift|Keys.F3)){FindNext(true);return true;}if(key==Keys.Escape&&store.Pref.Memo){SetMemo(false);return true;}if(key==(Keys.Control|Keys.Shift|Keys.P)){Preview();return true;}return base.ProcessCmdKey(ref msg,key);}

}
